(()=>{window.__qaProbe=null;(async()=>{try{
const KEY='xray:qa-session-sentinel';
const existing=localStorage.getItem(KEY);
const row=await new Promise((resolve)=>{const r=indexedDB.open('xray-qa-session',1);
  r.onupgradeneeded=()=>r.result.createObjectStore('s',{keyPath:'k'});
  r.onsuccess=()=>{const db=r.result;const q=db.transaction('s').objectStore('s').get('sentinel');
    q.onsuccess=()=>{db.close();resolve(q.result||null)};q.onerror=()=>{db.close();resolve(null)}};
  r.onerror=()=>resolve(null)});
if(existing||row){
  window.__qaProbe={verdict:'state survived a previous run under this session name',
    localStorageSentinel:existing,indexedDbSentinel:row?row.v:null,
    localStorageKeys:Object.keys(localStorage).length,
    projectKeys:Object.keys(localStorage).filter(k=>/xray:/.test(k)).slice(0,12)};
  return}
localStorage.setItem(KEY,'written');
await new Promise((resolve,reject)=>{const r=indexedDB.open('xray-qa-session',1);
  r.onupgradeneeded=()=>r.result.createObjectStore('s',{keyPath:'k'});
  r.onsuccess=()=>{const db=r.result;const tx=db.transaction('s','readwrite');
    tx.objectStore('s').put({k:'sentinel',v:'written'});
    tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}};
  r.onerror=()=>reject(r.error)});
window.__qaProbe={verdict:'fresh profile - nothing was here, a sentinel has now been written',
  localStorageKeys:Object.keys(localStorage).length};
}catch(e){window.__qaProbe={verdict:'error',detail:String(e)}}})();return 'probing profile'})()
